var A_MAG = 17.625, B_MAG = 243.04;
function dewPoint(T, RH){
  if(!(RH >= 0 && RH <= 100)) return NaN;
  var alpha = Math.log(RH/100) + A_MAG*T/(B_MAG+T);
  return B_MAG*alpha/(A_MAG - alpha);
}
function satVaporPressure(T){ return 6.112 * Math.exp(17.67*T/(T+243.5)); }
function absoluteHumidity(T, RH){
  var e = satVaporPressure(T) * 100 * RH/100; // Pa
  return 2.1674 * e / (273.15 + T);           // g/m³
}
var EXPORTS = { dewPoint:dewPoint, satVaporPressure:satVaporPressure, absoluteHumidity:absoluteHumidity, A_MAG:A_MAG, B_MAG:B_MAG };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DewPointForgePure = EXPORTS; }
